actions.script:
if (!ec.user.isInGroup('ADMIN')) { ec.web.sendError(403,'Forbidden',null); return }
def today = ec.user.nowTimestamp.toLocalDateTime().toLocalDate()
todayString = today.toString()
def tenants = ec.entity.find('zenith.erp.saas.SaasTenant').orderBy('tenantName').orderBy('tenantId').list()
def search = (tenantSearch ?: '').toString().trim().toLowerCase(java.util.Locale.ROOT)
tenantOptions = tenants
tenantRows = tenants.findAll { t -> !search || [t.tenantName,t.tenantId,t.organizationPartyId,t.planId].any { (it ?: '').toLowerCase(java.util.Locale.ROOT).contains(search) } }
def plans = ec.entity.find('zenith.erp.saas.SaasPlan').orderBy('sortOrder').list()
planNames = plans.collectEntries { [(it.planId):it.planName] }
availablePlans = plans.findAll { it.isActive == 'Y' }
grants = ec.entity.find('zenith.erp.saas.SaasTenantConfig').condition('configKey','MANUAL_PLAN_SUBSCRIPTION').list().collectEntries { [(it.tenantId):it.configValue] }
def subscriptions = ec.entity.find('zenith.erp.saas.SaasSubscription').orderBy('-startDate').orderBy('-lastUpdatedStamp').orderBy('-subscriptionId').list()
currentSubs = [:]
tenants.each { t -> currentSubs[t.tenantId] = grants[t.tenantId] ? subscriptions.find { it.tenantId == t.tenantId && it.subscriptionId == grants[t.tenantId] } : subscriptions.find { it.tenantId == t.tenantId && it.statusId in ['SubActive','SubTrial','SubPastDue','SubPaused'] } }
selectedTenant = tenantId ? tenants.find { it.tenantId == tenantId } : null
selectedSub = selectedTenant ? currentSubs[selectedTenant.tenantId] : null
selectedPlan = selectedTenant ? plans.find { it.planId == selectedTenant.planId } : null
selectedModules = selectedTenant ? ec.entity.find('zenith.erp.saas.SaasPlanModule').condition('planId',selectedTenant.planId).orderBy('moduleId').list().collect { it.moduleId } : []
selectedStatus = selectedTenant ? ec.entity.find('moqui.basic.StatusItem').condition('statusId',selectedTenant.statusId).useCache(true).one()?.description : ''
elapsedDays = { sub ->
    if (!sub?.startDate) return 0L
    def start = new java.sql.Date(sub.startDate.time).toLocalDate()
    def end = sub.endDate ? new java.sql.Date(sub.endDate.time).toLocalDate() : today
    Math.max(0L,java.time.temporal.ChronoUnit.DAYS.between(start,end < today ? end : today)+1L)
}
daysRemaining = { sub -> sub?.endDate ? Math.max(0L,java.time.temporal.ChronoUnit.DAYS.between(today,new java.sql.Date(sub.endDate.time).toLocalDate())+1L) : null }
manualCount = tenants.count { it.statusId == 'SaasTenantActive' && grants[it.tenantId] && currentSubs[it.tenantId]?.statusId == 'SubActive' && (daysRemaining(currentSubs[it.tenantId]) ?: 0) > 0 }
endingCount = tenants.count { it.statusId == 'SaasTenantActive' && grants[it.tenantId] && currentSubs[it.tenantId]?.statusId == 'SubActive' && (daysRemaining(currentSubs[it.tenantId]) ?: 0) in 1..7 }
assignForm = [tenantId:selectedTenant?.tenantId,newPlanId:selectedTenant?.planId,accessUntil:grants[selectedTenant?.tenantId] && (daysRemaining(selectedSub) ?: 0) > 0 ? selectedSub.endDate.toString() : '']
